(function(){
'use strict';
const D=window.WATER_DATA,E=window.WATER_ENGINE,Q=D.questions,chapters=D.chapters,M=window.WATER_MATERIALS;
const SC=window.SWEET_COACH,HW=window.WATER_HOMEWORK;
const byId=Object.fromEntries(Q.map(q=>[q.id,q]));
const KEY='water-quest-progress-v1';
const XT=window.WATER_EXAM,types=XT.types;
let state=E.fresh(),storageOK=true,loadWarning=false,screen='map',filter={ch:'all',type:'all',scope:'all',search:''},page=1,choice=null,toastTimer;
let materialId='concise',materialPage=1;
function materialLink(id,p,label){return `<button class="text-btn" data-action="read-material" data-value="${id}" data-page="${p}">${esc(label)}</button>`;}
function sourceLinks(q){const c=M.chapters.find(c=>c.ch===q.ch);return '<div class="source-links">'+materialLink('concise',c.concise,'看本章复习重点 →')+materialLink('complete',c.complete[0],'看完整解释 →')+(q.referenceNumber?materialLink('answers',q.referenceNumber,'对照新解答 · 第 '+q.referenceNumber+' 题 →'):'')+'</div>';}
function openMaterial(id,p=1){const file=M.files.find(f=>f.id===id);if(!file)return;materialId=id;materialPage=Math.min(file.pages,Math.max(1,Number.isFinite(Number(p))?Math.floor(Number(p)):1));goto('reader');}
function materialFile(){return M.files.find(f=>f.id===materialId)||M.files[0];}
function fileSize(bytes){return (bytes/1024/1024).toFixed(1)+' MB';}
function downloadLinks(f){return f.parts.map((p,i)=>`<a class="download-link" href="materials/${p.file}" download="${esc(f.title)}${f.parts.length>1?'-第'+p.start+'-'+p.end+'页':''}.pdf"><span>${f.parts.length>1?'第 '+(i+1)+' 卷 · 原第 '+p.start+'—'+p.end+' 页':'下载 PDF'}</span><small>${fileSize(p.bytes)} ↓</small></a>`).join('')+(f.word?`<a class="download-link word-link" href="materials/${f.word}" download="${esc(f.original)}.docx"><span>下载可编辑 Word</span><small>DOCX ↓</small></a>`:'');}
function materialsView(){return title('YOUR STUDY LIBRARY','三份资料，串起复习与原题。','先抓重点，再查完整解释，最后对照新解答巩固老师的 26 道题。',`<button class="btn" data-action="read-material" data-value="concise" data-page="1">阅读精简版 ${icon('arrow',16)}</button>`)+`<section class="materials-intro"><div>${icon('book',25)}</div><p><strong>10 页精简重点 · 34 页完整手册 · 26 题原文解答</strong><br>新增解答支持按题阅读与原 Word 下载；原有两份资料仍可翻页及下载 PDF。</p></section><div class="materials-grid">${M.files.map((f,i)=>`<article class="material-card ${i===0?'recommended':''}"><div class="material-top"><span class="tag ${i===0?'gold':''}">${esc(f.kind==='复习整理'?(i===0?'推荐先读 · 精简重点':'深入复习 · 完整讲解'):f.kind)}</span><span class="material-pages">${f.pages} ${f.unit||'页'}</span></div><div class="material-title"><div class="paper-icon">${icon('book',25)}</div><div><h2>${esc(f.title)}</h2><p>${esc(f.subtitle)}</p></div></div><p class="material-description">${esc(f.description)}</p><div class="material-original">${esc(f.original)}</div><div class="material-actions"><button class="btn small" data-action="read-material" data-value="${f.id}" data-page="1">在线阅读 ${icon('arrow',14)}</button></div><div class="material-downloads">${downloadLinks(f)}</div></article>`).join('')}</div>${window.WATER_REFERENCE_UI.auditOverview()}<section class="chapter-index"><div class="section-head"><h2>按章节快速查阅</h2><small>点击页码，直接打开对应内容</small></div><div class="table-scroll"><table><thead><tr><th>复习章节</th><th>10 页精简版</th><th>34 页完整手册</th></tr></thead><tbody>${M.chapters.map(c=>`<tr><th scope="row">${c.ch}. ${c.title}</th><td>${materialLink('concise',c.concise,'第 '+c.concise+' 页')}</td><td>${materialLink('complete',c.complete[0],'第 '+c.complete.join('—')+' 页')}</td></tr>`).join('')}<tr><th scope="row">课堂题与自测</th><td>${materialLink('concise',9,'第 9—10 页')}</td><td>${materialLink('complete',29,'第 29—31 页')}</td></tr></tbody></table></div></section>`;}
function readerView(){const f=materialFile();if(f.format==='questions')return window.WATER_REFERENCE_UI.view(materialPage,{title,materialLink});const part=f.parts[0],url=`materials/${part.file}#page=${materialPage}&zoom=page-width`;return title('READ. RECALL. PRACTICE.',esc(f.title),`${esc(f.original)} · 第 ${materialPage} / ${f.pages} 页`,'<button class="btn secondary small" data-action="nav" data-value="materials">← 全部资料</button>')+`<div class="reader-toolbar"><label class="sr-only" for="material-select">切换资料</label><select id="material-select">${M.files.map(item=>`<option value="${item.id}" ${item.id===f.id?'selected':''}>${item.title}</option>`).join('')}</select><div class="reader-paging"><button class="btn secondary small" data-action="read-material" data-value="${f.id}" data-page="${materialPage-1}" ${materialPage===1?'disabled':''}>上一页</button><label for="material-page">页码</label><input id="material-page" type="number" min="1" max="${f.pages}" value="${materialPage}" aria-label="资料页码"><button class="btn secondary small" data-action="material-jump">跳转</button><button class="btn secondary small" data-action="read-material" data-value="${f.id}" data-page="${materialPage+1}" ${materialPage===f.pages?'disabled':''}>下一页</button></div><button class="text-btn" data-action="reader-zoom" aria-pressed="false">放大阅读</button><a class="text-btn" href="${url}" target="_blank" rel="noopener">打开 PDF ↗</a></div><div class="review-page-wrap" id="review-page-wrap"><img class="review-page-image" src="materials/${f.id}/page-${String(materialPage).padStart(2,'0')}.jpg" alt="${esc(f.title)}第 ${materialPage} 页" decoding="async"></div><div class="reader-foot"><p class="reader-note">保留文档原有排版与重点颜色。需要打印或复制文字时，可下载 PDF 或可编辑的 Word。</p><a class="btn secondary small" href="materials/${part.file}" download="${esc(f.original)}.pdf">下载 PDF ↓</a><a class="btn secondary small" href="materials/${f.word}" download="${esc(f.original)}.docx">下载 Word ↓</a></div>`;}
function readMaterialRoute(){const hash=location.hash;const practice=hash.match(/^#practice(?:\/(all|fill|boolean|single|multi|short|number|definition))?$/);if(practice){filter={ch:'all',type:practice[1]||'all',scope:'all',search:''};screen='bank';return true;}if(HW.route(hash)){screen='homework';return true;}if(hash==='#materials'){screen='materials';return true;}const match=hash.match(/^#read\/([a-z]+)\/(\d+)$/);if(match&&M.files.some(f=>f.id===match[1])){materialId=match[1];materialPage=Math.max(1,Math.min(materialFile().pages,Number(match[2])));screen='reader';return true;}return false;}
try{const raw=localStorage.getItem(KEY);if(raw)state=E.validateState(JSON.parse(raw),Q);}catch(e){loadWarning=true;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch(e){storageOK=false;toast('浏览器未允许保存，请在学习记录中导出备份。');}}
function esc(x){return String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function icon(name,size=20){const paths={drop:'<path d="M12 3C9 7 5 11 5 15a7 7 0 0 0 14 0c0-4-4-8-7-12Z"/><path d="M8 15a4 4 0 0 0 4 4"/>',map:'<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2V5Z"/><path d="M9 3v16m6-14v16"/>',book:'<path d="M3 4h6a4 4 0 0 1 3 2 4 4 0 0 1 3-2h6v16h-6a4 4 0 0 0-3 1 4 4 0 0 0-3-1H3V4Z"/><path d="M12 6v15"/>',wrong:'<path d="M6 3h12v18H6zM9 7h6m-6 4h6m-6 4 6 3m0-3-6 3"/>',chart:'<path d="M4 3v17h17M8 15v-4m5 4V6m5 9V9"/>',valve:'<path d="M2 10h5l10 8V6L7 14H2m20-4h-5M12 10V3M8 3h8"/>',supply:'<path d="M5 21V6h14v15M3 21h18M9 10h6m-6 4h6m-6 4h6M8 3h8v3"/>',fire:'<path d="M13 2c3 6-1 7 3 10 2-2 2-3 2-3 6 8 0 13-6 13C5 22 1 16 7 9c0 4 1 5 3 5-1-4 3-6 3-12Z"/>',drain:'<path d="M4 3v9a7 7 0 0 0 14 0V3m-10 0v9a3 3 0 0 0 6 0V3M2 3h8m2 0h8m1 13-2 3 2 2"/>',heat:'<path d="M5 21V4h14v17zM3 21h18M9 8c-2 2 2 3 0 5m6-5c-2 2 2 3 0 5M9 17h6"/>',tower:'<path d="M6 22V5l12-3v20M3 22h18M10 7h4m-4 4h4m-4 4h4m-4 4h4"/>',pool:'<path d="M2 16c3-3 5 3 8 0s5 3 8 0 4 0 4 0M2 21c3-3 5 3 8 0s5 3 8 0 4 0 4 0M5 14V5a2 2 0 0 1 4 0m4 9V5a2 2 0 0 1 4 0M5 8h8m-8 4h8"/>',calc:'<rect x="5" y="2" width="14" height="20" rx="2"/><path d="M8 6h8M8 11h2m4 0h2m-8 4h2m4 0h2m-8 4h2m4 0h2"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4m-4 5v2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',check:'<path d="m4 12 5 5L20 6"/>',trophy:'<path d="M7 3h10v6a5 5 0 0 1-10 0V3Zm0 2H3v3a4 4 0 0 0 4 4m10-7h4v3a4 4 0 0 1-4 4m-5 2v6m-5 1h10"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 10v7m0-11v1"/>'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.drop}</svg>`;}
function buddy(){return `<svg class="water-buddy" viewBox="0 0 160 170" fill="none" aria-hidden="true"><g stroke="#243d55" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"><path d="M55 146l-7 12h20l5-9m24-2 6 11h19l-11-15" fill="#ffcf65"/><path d="M80 16C69 40 28 72 28 104c0 31 23 49 52 49s53-18 53-49c0-32-42-64-53-88Z" fill="#73cef1"/><path d="M41 108c1 21 17 33 36 33" stroke="#b8eeff" stroke-width="7"/><path d="M39 111l-17-6-9-13m111 16 19-5 7-13"/><path d="m11 91 1-8m2 8 6-6m128 3 6-5m-5 7 8 1"/><path d="M47 62c1-24 14-37 33-37s32 13 34 37" fill="#ffda70"/><path d="M74 29v24m13-24v24" stroke="#be8b30" stroke-width="3"/><rect x="38" y="59" width="85" height="12" rx="6" fill="#ffe99f"/><path d="M63 92v7m35-7v7" stroke-width="5"/><path d="M72 107q9 12 18 0"/><path d="M49 106h9m45 0h9" stroke="#f69d93" stroke-width="5"/></g><ellipse cx="57" cy="80" rx="6" ry="3" fill="#c7f4ff" transform="rotate(-25 57 80)"/></svg>`;}
function art(){return `<svg viewBox="0 0 460 340" role="img" aria-label="蓝色和粉色水滴伙伴一起读书，爱心在身旁轻轻浮动"><g stroke="#243d55" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><ellipse cx="246" cy="300" rx="169" ry="19" fill="#bce2ef" stroke="none"/><g fill="#fffef7"><path d="M44 76c-15-1-13-20 1-20 4-19 33-19 37-2 19-5 28 21 7 22Z"/><path d="M332 53c-12-2-13-17 1-20 2-20 29-23 37-5 17-5 29 16 14 25Z"/></g><circle cx="393" cy="106" r="26" fill="#ffdb72"/><path d="M385 103v3m15-3v3m-14 9q6 6 12 0"/><g fill="#fffdf5"><path d="M66 282V158l53-22 44 22v124Z"/><path d="M65 158h98M120 137v145"/><path d="M303 283V139h72v144Z"/><path d="M296 139h86v-13h-86Z" fill="#ffcf84"/><path d="M322 126V98h36v28" fill="#c9e8f7"/></g><g fill="#a7dbf5"><path d="M79 174h24v26H79zm0 42h24v26H79zm52-43h18v25h-18zm0 42h18v25h-18zM318 154h15v23h-15zm26 0h15v23h-15zm-26 38h15v23h-15zm26 0h15v23h-15z"/></g><path d="M42 274h26v-30h30v42h306" fill="none" stroke="#243d55" stroke-width="15"/><path d="M42 274h26v-30h30v42h306" fill="none" stroke="#7bc7dc" stroke-width="10"/><path d="M44 273h22m35 13h27m198 0h30" fill="none" stroke="#d7f8ff" stroke-width="3" stroke-dasharray="4 6"/><circle cx="369" cy="286" r="12" fill="#f8bc9d"/><path d="M361 286h16m-8-8v16"/><g transform="translate(110 101) scale(.92)"><g class="art-float" fill="none">${buddy().replace(/^<svg[^>]*>/,'').replace(/<\/svg>$/,'')}</g></g><g transform="translate(223 109) scale(.88)"><g class="art-float sweet-float" fill="none">${buddy().replace(/^<svg[^>]*>/,'').replace(/<\/svg>$/,'').replaceAll('#73cef1','#f4a6bf').replaceAll('#b8eeff','#ffe3ed').replaceAll('#c7f4ff','#ffe8ef')}</g></g><g transform="translate(223 97)"><path class="sweet-heart-art" d="M0 8C-23-5-17-23-6-19c4 1 6 5 6 5s3-4 7-5C20-24 23-6 0 8Z" fill="#ef91af" stroke="#98556c" stroke-width="2"/></g><g transform="translate(176 260) rotate(-5)"><path d="M0 0h45l11 9 11-9h42v40H67l-11 5-11-5H0Z" fill="#fffef7"/><path d="M56 9v36M12 11h24M12 20h24m40-9h20m-20 9h20" stroke="#7a9cae"/><path d="M0 35h45l11 6 11-6h42v9H67l-11 5-11-5H0Z" fill="#ffce70"/></g><g class="art-spark" fill="#fff7c5"><path d="m180 48 4 10 11 3-11 4-4 11-4-11-11-4 11-3Z"/><path d="m415 212 3 8 9 3-9 3-3 9-3-9-9-3 9-3Z"/></g><g transform="translate(52 107) rotate(-9)"><rect width="92" height="31" rx="10" fill="#fffdf3"/><path d="m12 15 4 4 8-9" stroke="#31856f"/><text x="33" y="20" fill="#39556c" stroke="none" font-size="12" font-family="system-ui,sans-serif" font-weight="800">WITH YOU</text></g><g transform="translate(281 67) rotate(7)"><rect width="85" height="31" rx="10" fill="#ffe4d4"/><path d="m13 9 2 5 5 1-4 3 1 5-4-3-4 3 1-5-4-3 5-1Z" fill="#f7bd58" stroke-width="1.5"/><text x="27" y="20" fill="#624b43" stroke="none" font-size="11" font-family="system-ui,sans-serif" font-weight="800">SWEET ♡</text></g><path d="M40 299h374" stroke="#739fb7"/></g></svg>`;}
const countPassed=()=>chapters.filter(c=>state.completed[c.id]?.passed).length;
const nextChapter=()=>chapters.find(c=>!state.completed[c.id]?.passed)?.id||8;
const totalStars=()=>Object.values(state.completed).reduce((a,c)=>a+c.stars,0);
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.className='show';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='',3600);}
function confirmAction(title,text,action,label='确认'){const dialog=document.getElementById('dialog');document.getElementById('dialog-content').innerHTML=`<h2>${esc(title)}</h2><p>${esc(text)}</p><div class="dialog-actions"><button class="btn secondary" id="cancel-dialog">取消</button><button class="btn" id="accept-dialog">${esc(label)}</button></div>`;dialog.showModal();document.getElementById('cancel-dialog').onclick=()=>dialog.close();document.getElementById('accept-dialog').onclick=()=>{dialog.close();action();};}
function goto(name){screen=name;page=1;choice=null;const hash=name==='bank'?'#practice/'+filter.type:name==='homework'?HW.hash():name==='reader'?`#read/${materialId}/${materialPage}`:name==='materials'?'#materials':'';try{history.replaceState(null,'',location.pathname+location.search+hash);}catch(e){}render();window.scrollTo(0,0);document.getElementById('main')?.focus({preventScroll:true});}
function shell(body){const nav=[['map','map','闯关地图'],['bank','book','题库练习'],['wrong','wrong','错题本'],['materials','book','复习资料'],['homework','book','课后题复习'],['records','chart','学习记录']];const active=screen==='quiz'||screen==='result'?'map':screen==='reader'?'materials':screen;
document.getElementById('app').innerHTML=`<div class="layout"><aside class="sidebar"><a class="brand" href="#" data-action="nav" data-value="map"><div class="brand-mark">${buddy()}</div><div><strong>甜蜜蜜复习</strong><small>STUDY WITH YOU</small></div></a><div class="nav-label">两个人的小小复习角</div><nav class="nav" aria-label="主导航">${nav.map(([id,i,t])=>`<button data-action="nav" data-value="${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${icon(i)}${t}${id==='wrong'&&state.wrong.length?`<span class="badge">${state.wrong.length}</span>`:''}</button>`).join('')}</nav><div class="side-note"><strong>今天也要一起加油。</strong><br>建筑设备 · 水<br><span class="tiny-dot"></span>${storageOK?'进度保存在当前浏览器':'保存受限，请导出备份'}<br><button class="text-btn" data-action="nav" data-value="about">题库来源与使用说明</button></div></aside><div class="main-wrap"><header class="topbar"><div class="breadcrumbs">建筑学 / 建筑设备<span>${esc(({map:'闯关地图',bank:'题库练习',wrong:'错题复习',records:'学习记录',quiz:'正在挑战',result:'本次结果',about:'题库说明',notes:'考点速记',materials:'复习资料',reader:'资料阅读',homework:'课后题复习'})[screen])}</span></div><div class="top-meta"><span>一起进步，也一起甜蜜。</span><span class="sweet-label">L&amp;M</span>${window.WATER_SOUND?.control()||''}<span class="stars">★ ${totalStars()}</span><div class="avatar" aria-label="水滴学习伙伴">${buddy()}</div></div></header><main class="main" id="main" tabindex="-1">${!storageOK?'<div class="storage-warning">当前浏览器无法自动保存。离开前请到“学习记录”导出备份。</div>':''}${loadWarning?'<div class="storage-warning">未能读取原来的进度，已暂用空白记录。可在“学习记录”导入之前导出的备份。</div>':''}${body}</main><footer class="footer"><span>甜蜜蜜复习 · L&amp;M</span><button class="text-btn" data-action="nav" data-value="about">依据课程资料编写 · 非真实考卷</button></footer></div></div>`;}
function title(eyebrow,h1,sub,extra=''){return `<div class="page-title"><div><span class="eyebrow">${eyebrow}</span><h1>${h1}</h1><p class="subtitle">${sub}</p></div>${extra}</div>`;}
function stats(){const attempts=Object.values(state.stats).reduce((n,s)=>n+s.attempts,0),correct=Object.values(state.stats).reduce((n,s)=>n+s.correct,0);return `<div class="stats-row"><div class="stat"><span>已通关</span><strong>${countPassed()}<small>/ 8 关</small></strong></div><div class="stat"><span>已练题目</span><strong>${Object.keys(state.stats).length}<small>/ ${Q.length}</small></strong></div><div class="stat"><span>累计正确率</span><strong>${attempts?Math.round(correct/attempts*100):'—'}<small>${attempts?'%':''}</small></strong></div><div class="stat"><span>待巩固错题</span><strong>${state.wrong.length}<small>道</small></strong></div></div>`;}
function sweetExam(){const c=SC.countdown(state.sweet);return `<section class="exam-banner" aria-label="考试倒计时"><div><span class="eyebrow">OUR EXAM COUNTDOWN</span><h2>一起奔向考试那一天</h2><p id="sweet-exam-date">${esc(state.sweet.exam.replace('T',' '))} · 北京时间</p></div><div class="exam-clock" id="sweet-countdown">${sweetClock(c)}</div><details class="exam-edit"><summary>调整考试时间</summary><label for="sweet-exam-time">考试时间（北京时间）</label><input id="sweet-exam-time" type="datetime-local" value="${esc(state.sweet.exam)}"><button class="btn small" data-action="sweet-exam-save">保存时间</button><small>资料中的考试通知为 11 月 11 日 12:20—13:50；如有新通知，可在此修改。</small></details></section>`;}
function sweetClock(c){return c.arrived?'<strong class="exam-arrived">考试时间已到，愿你从容发挥 ♡</strong>':`<span><b>${c.days}</b>天</span><span><b>${String(c.hours).padStart(2,'0')}</b>小时</span><span><b>${String(c.minutes).padStart(2,'0')}</b>分</span>`;}
function sweetBoard(){const d=SC.today(state.sweet),debts=Object.keys(state.sweet.debt),plan=SC.plan(state.sweet),current=plan.find(p=>p.today),examDate=state.sweet.exam.slice(0,10),todayKey=SC.dayKey();return `<section class="sweet-coach"><div class="section-head"><h2>努力有奖励，错题有回访</h2><span class="sweet-balance">♡ ${state.sweet.hearts} 颗心心</span></div><div class="coach-grid"><article class="coach-card"><span class="eyebrow">TODAY'S LITTLE PROMISE</span><h3>${d.seen.length>=12?'今天的 12 题目标完成啦！':'今天，认真练 12 道不同的题'}</h3><div class="coach-goal"><strong>${Math.min(d.seen.length,12)}<small>/12 题</small></strong><span>已连续答对 ${d.streak} 道新题</span></div><div class="progress-track"><i style="width:${Math.min(d.seen.length/12,1)*100}%"></i></div><p>${current?esc(current.title+'：'+current.detail):todayKey<plan[0].date?'先用题库摸底，按自己的进度补齐基础。':todayKey>examDate?'辛苦啦！考试之后也可以回看已经掌握的知识。':'今天轻回顾，带着准备好的自己去考试。'}</p><div class="coach-actions"><button class="btn small" data-action="${current?.chapter?'chapter-bank':'nav'}" data-value="${current?.chapter||'bank'}">${current?.chapter?'练习今日章节':'去题库练习'} →</button><button class="btn secondary small" data-action="sweet-repair" ${!debts.length?'disabled':''}>错题回访（${debts.length}）</button></div><p class="coach-note">${debts.length?'待回访题目重练答对后解除；原有关卡星级不会扣除。':'暂时没有待回访任务。每次认真复盘，都算向前一步。'}</p></article><article class="coach-card rewards-card"><span class="eyebrow">A LITTLE SWEET REWARD</span><h3>攒一点心心，领一点甜蜜</h3><div class="reward-list">${SC.rewards.map(r=>`<div class="reward-item"><span class="reward-icon" aria-hidden="true">${r.icon}</span><div><strong>${r.title}</strong><small>${r.cost} 颗心心</small></div><button class="btn secondary small" data-action="sweet-redeem" data-value="${r.id}" ${state.sweet.hearts<r.cost?'disabled':''}>${state.sweet.hearts<r.cost?'还差 '+(r.cost-state.sweet.hearts)+' 颗':'兑换'}</button></div>`).join('')}</div><p class="coach-note">奖励是给自己的小约定；心愿可以和对方一起商量。</p>${state.sweet.rewards.length?`<details class="sweet-reward-history"><summary>已领到 ${state.sweet.rewards.length} 张奖励卡</summary>${state.sweet.rewards.slice(0,5).map(r=>`<p>${esc(SC.rewards.find(x=>x.id===r.id).title)} · ${SC.dayKey(r.at)}</p>`).join('')}</details>`:''}</article></div><details class="coach-rules"><summary>查看奖励与小惩戒规则</summary><ul><li>每道题当天首次答对 +1 心心；连续答对 3 道当天未获奖的新题，额外 +2（每天一次）。重复刷同一道题不增加连对数。</li><li>每天完成 12 道不同题目，额外 +3 心心（每天一次）。答对之前的错题额外 +1，同一道错题每天最多一次。</li><li>答错扣 1 心心，最低为 0；写至少 6 个字的易错提醒后才能进入下一题，再到错题回访中重练。</li><li>简答与名词解释按你对照要点后的自评结果计入。心心和关卡分数相互独立，原有星级不扣除。</li><li>每日目标和连对按北京时间零点重新统计；累计心心与待回访任务保留。进度备份包含奖励、提醒和考试时间。</li></ul></details><details class="coach-plan"><summary>考前冲刺安排 · ${plan[0].date.slice(5)} 至 ${examDate.slice(5)}</summary><div class="coach-days">${plan.map(p=>`<article class="coach-day ${p.today?'is-today':''}"><span>${p.date.slice(5).replace('-','月')}日 ${p.today?'· 今天':p.past?'· 已过日期':''}</span><h4>${p.title}</h4><p>${p.detail}</p></article>`).join('')}</div><small>这是复习建议；日期过去不代表已完成，以你的实际掌握为准。</small></details></section>`;}
function sweetFeedback(q,answer){if(!answer)return '';const debt=state.sweet.debt[q.id],receipt=state.sweet.receipt?.id===q.id?state.sweet.receipt:null;if(answer.correct)return `<div class="sweet-feedback good"><strong>♡ ${receipt?esc(receipt.text):'又弄懂一个知识点，给努力的你点个赞。'}</strong><small>当前 ${state.sweet.hearts} 颗心心 · 今日 ${SC.today(state.sweet).seen.length}/12 道不同题目</small></div>`;return `<section class="sweet-feedback repair" aria-label="易错点复盘"><h3>温柔小惩戒：留下一句提醒</h3><p>${receipt?esc(receipt.text):'先弄懂这题，再继续向前。'}。重练答对后解除本题回访任务。</p>${debt?.reviewed?`<div class="review-saved"><strong>✓ 已记录易错提醒</strong><p>${esc(debt.note)}</p><small>可以继续答题；这题仍需回访答对。</small></div>`:`<label for="sweet-review-note">我刚才容易弄错的是……</label><textarea id="sweet-review-note" rows="2" minlength="6" maxlength="300" placeholder="例如：水封至少 50 mm，通气管不能代替水封。"></textarea><div id="sweet-review-error" class="form-error" role="alert"></div><button class="btn secondary small" data-action="sweet-review" data-value="${q.id}">记住这点，继续加油</button>`}</section>`;}
function sweetAction(action,value){if(action==='sweet-exam-save'){const input=document.getElementById('sweet-exam-time');try{SC.examTime(input.value);state.sweet.exam=input.value;save();render();toast('考试时间已更新（北京时间）。');}catch(e){toast(e.message);input.focus();}return true;}if(action==='sweet-redeem'){try{const reward=SC.redeem(state.sweet,value);save();render();const dialog=document.getElementById('dialog');document.getElementById('dialog-content').innerHTML=`<div class="reward-dialog"><div aria-hidden="true">${reward.icon}</div><h2>${reward.title}</h2><p>${esc(reward.message)}</p><small>已用 ${reward.cost} 颗心心 · 剩余 ${state.sweet.hearts} 颗</small><button class="btn" data-action="sweet-close">收下这份甜蜜 ♡</button></div>`;dialog.showModal();window.WATER_SOUND?.play('reward');}catch(e){toast(e.message);}return true;}if(action==='sweet-close'){document.getElementById('dialog').close();return true;}if(action==='sweet-review'){try{SC.review(state.sweet,value,document.getElementById('sweet-review-note').value);save();const y=window.scrollY;render();window.scrollTo(0,y);document.querySelector('[data-action="next"]')?.focus({preventScroll:true});toast('易错提醒已记下，稍后重练这道题。');window.WATER_SOUND?.play('review');}catch(e){document.getElementById('sweet-review-error').textContent=e.message;document.getElementById('sweet-review-note').focus();}return true;}if(action==='sweet-repair'){const ids=Object.keys(state.sweet.debt);if(ids.length)start('wrong',null,ids);else toast('目前没有待回访任务。');return true;}return false;}

function mapView(){const next=nextChapter(),all=countPassed()===8;return title('OUR LITTLE STUDY CORNER','甜蜜蜜复习，一起向前。','把 26 个复习问题，一点一点装进我们的知识口袋。',`<span class="pill">${icon('book',13)} ${Q.length} 道精编题</span>`)+`${sweetExam()}<section class="hero"><div class="hero-copy"><span class="eyebrow">L&amp;M <span class="sweet-heart-inline" aria-hidden="true">♡</span></span><h2>L&amp;M的<br><b>甜蜜蜜</b></h2><p class="sweet-message">这是我们的爱情秘密 <span aria-hidden="true">♥</span></p><p class="sweet-study-note">一起闯关，一起把知识记牢。<br>7 章核心考点 + 公式计算营。</p><button class="btn" data-action="${all?'boss':'stage'}" data-value="${next}">${all?'挑战综合终章':countPassed()?'继续第 '+next+' 关':'开始第一关'} ${icon('arrow',17)}</button></div><div class="hero-art">${art()}</div></section>${state.session&&!state.session.done?`<div class="resume-banner"><span>上次进行到「${esc(state.session.title)}」第 ${state.session.cursor+1} / ${state.session.ids.length} 题，继续就好。</span><button class="btn small" data-action="resume">继续答题 →</button></div>`:''}${stats()}${examTypes()}<section class="hw-home-link"><div><strong>老师布置的课后题，单独复习。</strong><p>26 道复习题＋11 道课堂原题 · 原图、解析与答案核对说明</p></div><div class="hw-home-actions"><a class="btn small" href="#classroom">课堂原题 · 原图版 →</a><button class="text-btn" data-action="nav" data-value="homework">打开课后题</button></div></section>${sweetBoard()}<div class="dashboard"><section><div class="section-head"><h2>出发！闯关地图</h2><small>每关 12 题 · 答对 10 题即可通关</small></div><div class="stage-grid">${chapters.map(c=>{const unlocked=E.unlocked(state,c.id),done=state.completed[c.id],passed=done?.passed;return `<article class="stage-card ${!unlocked?'locked':passed?'stage-complete':c.id===next?'current':''}"><div class="stage-top"><div class="stage-icon">${icon(c.icon,24)}</div><span class="stage-no">LEVEL ${String(c.id).padStart(2,'0')}</span></div><h3>${c.title}</h3><p>${c.topics}</p><div class="stage-bottom">${passed?`<span class="stars" aria-label="${done.stars} 星">${'★'.repeat(done.stars)}${'☆'.repeat(3-done.stars)}</span>`:`<small>${!unlocked?'通过前一关解锁':done?'上次最高 '+done.score+' 分':Q.filter(q=>q.ch===c.id).length+' 题储备 · 随机抽 12 题'}</small>`}<button class="stage-button" data-action="stage" data-value="${c.id}" ${!unlocked?'disabled':''}>${passed?'再挑战 ↗':!unlocked?'待解锁':done?'再试一次 →':'开始挑战 →'}</button></div></article>`;}).join('')}</div><article class="boss-card"><div><span class="eyebrow" style="color:#d4c27d">FINAL CHALLENGE</span><h3>综合终章 · 水系统设计师</h3><p>24 道混合题 · 每章抽 3 题 · 答对 20 题通关</p></div><button class="btn" data-action="boss" ${!all?'disabled':''}>${all?'进入终章 →':'完成 8 关解锁'}</button></article>${state.completed.boss?.passed?'<div class="all-pass">✦ 已获“水系统设计师”称号。回看错题，把薄弱知识点补齐。</div>':''}</section><aside><section class="aside-card"><span class="eyebrow">YOUR NEXT STEP</span><h3>${all?'综合知识检验':'下一站 · '+chapters[next-1].title}</h3><p>${all?'把分散的知识连接成完整系统。':chapters[next-1].subtitle}</p><div class="rule-line"><span>路线进度</span><span>${countPassed()}/8</span></div><div class="progress-track"><i style="width:${countPassed()/8*100}%"></i></div><div class="divider"></div><p>不想按顺序？题库练习随时开放全部章节。</p><button class="btn secondary small" data-action="nav" data-value="bank">自由练习 ${icon('arrow',14)}</button></section><section class="aside-card"><span class="eyebrow">TODAY'S KEY POINT</span><div class="tip-number">50<small>mm</small></div><h3>水封深度，别记错。</h3><p>至少 50 mm。同一器具不得重复设水封；通气管保护水封，但不能代替水封。</p><button class="text-btn" data-action="nav" data-value="notes">查看全部考点速记 →</button></section><section class="aside-card"><h3>每一星，都有意义</h3><ul class="bullet-note"><li>正确率 ≥80%：★ 通关</li><li>正确率 ≥90%：★★ 熟练</li><li>全部答对：★★★ 掌握</li><li>多选需全对；错题答对后自动移出待巩固列表。</li></ul></section></aside></div>`;}
function start(mode,ch,explicitIds){if(mode==='stage'&&!E.unlocked(state,ch))return toast('请先通过前一关。');if(mode==='boss'&&countPassed()<8)return toast('请先完成 8 个关卡。');
 const run=()=>{let list,titleText;if(mode==='stage'){list=E.pick(Q.filter(q=>q.ch===ch),12);titleText=`第 ${ch} 关 · ${chapters[ch-1].title}`;}else if(mode==='boss'){list=E.shuffle(chapters.flatMap(c=>E.pick(Q.filter(q=>q.ch===c.id),3)));titleText='综合终章 · 水系统设计师';}else if(mode==='wrong'){list=E.shuffle((explicitIds||state.wrong).map(id=>byId[id]));titleText='错题重练';}else if(mode==='starred'){list=E.shuffle(state.starred.map(id=>byId[id]));titleText='收藏题训练';}else{list=E.pick(explicitIds?explicitIds.map(id=>byId[id]):filtered(),12);titleText=(filter.type==='definition'?'名词解释复习':types[filter.type]||'混合题')+' · '+(filter.ch==='all'?'全部章节':chapters[Number(filter.ch)-1].title);}
 if(!list.length)return toast('当前没有可练习的题目。');const orders={};for(const q of list)if(q.options)orders[q.id]=E.shuffle(q.options.map((_,i)=>i));state.session={mode,ch:ch||null,title:titleText,ids:list.map(q=>q.id),orders,cursor:0,answers:{},done:false,resultRecorded:false};choice=null;save();goto('quiz');};
 if(state.session&&!state.session.done)confirmAction('开始新的练习？','已作答记录和错题会保留，但当前未完成的挑战将被新练习替换。你也可以取消后继续上次挑战。',run,'开始新练习');else run();}
function rightAnswer(q,orders){if(E.isWritten(q))return q.answer;if(q.type==='boolean')return q.answer?'正确':'错误';if(q.type==='fill')return q.answer[0];if(q.type==='number')return q.answer+' '+q.unit;if(q.type==='single')return (orders?String.fromCharCode(65+orders.indexOf(q.answer))+' · ':'')+q.options[q.answer];return q.answer.map(i=>(orders?String.fromCharCode(65+orders.indexOf(i))+' · ':'')+q.options[i]).join('；');}
function responseText(q,r,orders){if(E.isWritten(q))return r.text+'（自评 '+r.points.filter(Boolean).length+'/'+q.points.length+' 个要点）';if(q.type==='boolean')return r?'正确':'错误';if(q.type==='single')return String.fromCharCode(65+orders.indexOf(r))+' · '+q.options[r];if(q.type==='multi')return r.map(i=>String.fromCharCode(65+orders.indexOf(i))+' · '+q.options[i]).join('；');return String(r);}
function tags(q){return `<div class="tags"><span class="tag">${types[XT.typeOf(q)]}</span><span class="tag ${q.tag==='考点模拟'?'':'gold'}">${esc(q.tag)}</span><span class="tag">${esc(q.topic)}</span></div>`;}
function starButton(q){const yes=state.starred.includes(q.id);return `<button class="star-btn" data-action="star" data-value="${q.id}" aria-label="${yes?'取消收藏':'收藏本题'}" aria-pressed="${yes}">${yes?'★':'☆'}</button>`;}
function definitionDraft(q){return state.session.definitionDraft||{id:q.id,text:'',reviewing:false,points:q.points.map(()=>false)};}
function definitionPoints(q,response,editable=false){
 const count=response?.points.filter(Boolean).length||0,brief=q.type==='definition',label=brief?'必背关键词':q.brief?'精简答案':'得分要点';
 if(editable)return `<fieldset class="definition-points"><legend>${label} · 逐项对照</legend>${q.points.map((point,i)=>`<label class="definition-point"><input type="checkbox" data-definition-point="${i}" ${response.points[i]?'checked':''}><span>${brief?'':`<b>要点 ${i+1}</b>`}${esc(point)}</span></label>`).join('')}</fieldset><p class="definition-score" id="definition-score" aria-live="polite">已勾选 ${count} / ${q.points.length} 个要点</p>`;
 const items=q.points.map((point,i)=>`<li class="${response?(response.points[i]?'point-hit':'point-miss'):''}">${response?(response.points[i]?'✓ 已掌握 · ':'○ 待巩固 · '):''}${esc(point)}</li>`).join('');
 return `<div class="definition-rubric"><h4>${label}${response?' · 自评 '+count+' / '+q.points.length:''}</h4>${brief?`<ul class="definition-keywords">${items}</ul>`:`<ol>${items}</ol>`}</div>`;
}
function hasBriefAnswer(q){return q.type==='definition'||!!q.brief;}
function definitionDetails(q){return `<details class="definition-more"><summary>展开解释与出处</summary><div>${q.fullAnswer?`<p><strong>理解补充：</strong>${esc(q.fullAnswer)}</p>`:''}<p><strong>易错提醒：</strong>${esc(q.fullExplanation||q.explanation)}</p><div class="source">依据：${esc(q.source)}${sourceLinks(q)}${q.homeworkId?`<a class="text-btn" href="#homework/${q.homeworkId}">查看教师原题与课堂原图 →</a>`:''}</div></div></details>`;}
function definitionReview(q,d){const brief=hasBriefAnswer(q);return `<section class="definition-review" tabindex="-1"><span class="eyebrow">CHECK YOUR KEY POINTS</span><h3>对照答案，完成自评</h3>${q.brief?'':`<p class="right-answer"><strong>${brief?'精简答案':'参考答案'}：</strong>${esc(q.answer)}</p>`}<p>${brief?'只勾选刚才已表达清楚、没有矛盾的要点；意思准确、要点齐全记为答对。':'只勾选你刚才已表达清楚、且没有矛盾的要点；措辞可以不同。每点按 1 分练习，全部要点掌握才记为答对。'}</p>${definitionPoints(q,d,true)}${q.brief?`<p class="quiz-hint">${esc(q.explanation)}</p>`:''}${brief?definitionDetails(q):`<p class="quiz-hint">${esc(q.explanation)}</p>`}<p class="quiz-hint">练习自评，不代表老师正式评分；提交后记录结果。</p></section>`;}
function gradeDefinition(){const s=state.session;if(!s||s.done)return;const q=byId[s.ids[s.cursor]],d=s.definitionDraft;if(!E.isWritten(q)||s.answers[q.id]||!d?.reviewing||d.id!==q.id)return;const response={text:d.text,points:[...d.points]};s.answers[q.id]={response,correct:E.record(state,q,response)};window.WATER_SOUND?.play(s.answers[q.id].correct?'correct':'incorrect');delete s.definitionDraft;save();render();document.querySelector('.feedback')?.scrollIntoView({block:'nearest'});document.querySelector('[data-action="next"]')?.focus({preventScroll:true});}
function quizView(){const s=state.session;if(!s){screen='map';return mapView();}if(s.done){screen='result';return resultView();}const q=byId[s.ids[s.cursor]],answer=s.answers[q.id],order=s.orders[q.id],draft=E.isWritten(q)?definitionDraft(q):null,reviewing=!!draft?.reviewing;let form='';if(q.options){form=`<div class="options" role="group" aria-label="${types[XT.typeOf(q)]}选项">${order.map((i,j)=>{const picked=answer?(q.type==='multi'?answer.response.includes(i):answer.response===i):(q.type==='multi'?Array.isArray(choice)&&choice.includes(i):choice===i);const good=q.type==='multi'?q.answer.includes(i):q.answer===i;return `<button class="option ${picked?'selected':''} ${answer&&good?'correct':''} ${answer&&picked&&!good?'incorrect':''}" data-action="option" data-value="${i}" aria-pressed="${!!picked}" ${answer?'disabled':''}><span class="letter">${String.fromCharCode(65+j)}</span><span>${esc(q.options[i])}</span>${answer&&good?'<span style="margin-left:auto" aria-label="正确选项">✓</span>':''}</button>`;}).join('')}</div>`;}else if(q.type==='boolean'){form=`<div class="options" role="group" aria-label="判断题选项">${[true,false].map((v,i)=>`<button class="option ${(answer?answer.response:choice)===v?'selected':''} ${answer&&q.answer===v?'correct':''} ${answer&&answer.response===v&&!answer.correct?'incorrect':''}" data-action="boolean" data-value="${v}" aria-pressed="${(answer?answer.response:choice)===v}" ${answer?'disabled':''}><span class="letter">${i?'×':'✓'}</span><span>${v?'正确':'错误'}</span></button>`).join('')}</div>`;}else if(E.isWritten(q)){form=`<label class="quiz-hint" for="definition-input">${q.type==='definition'?'用一句话写清含义，保留关键作用':'用自己的话分点作答，写清含义、作用或过程'}</label><textarea id="definition-input" class="definition-input ${q.type==='definition'?'concise-input':''}" rows="${q.type==='definition'?3:5}" maxlength="4000" placeholder="先独立写出答案，再对照参考答案逐项自评。" ${answer||reviewing?'disabled':''}>${esc(answer?answer.response.text:draft.text)}</textarea><p class="quiz-hint">草稿自动保存。按 Enter 换行，点击按钮后再看答案。</p>${reviewing&&!answer?definitionReview(q,draft):''}`;}else{form=`<label class="quiz-hint" for="answer-input">${q.type==='number'?'填写数值，单位已给出':'填写空缺处的关键词'}</label><div class="answer-entry"><input id="answer-input" class="answer-input" autocomplete="off" ${q.type==='number'?'inputmode="decimal"':''} placeholder="${q.type==='number'?'在这里输入数值':'在这里填写答案'}" value="${esc(answer?answer.response:choice||'')}" ${answer?'disabled':''}>${q.unit?`<span class="input-unit">${esc(q.unit)}</span>`:''}</div>`;}
const feedback=answer?`<section class="feedback ${answer.correct?'':'incorrect'}" role="status" aria-live="polite"><h3>${E.isWritten(q)?(answer.correct?'✓ 自评：全部要点已掌握。':'自评：还有要点需要巩固。'):(answer.correct?'✓ 回答正确，继续保持。':'这题先记下，下次一定会。')}</h3>${q.brief?'':`<p class="right-answer">${q.type==='definition'?'精简答案':E.isWritten(q)?'参考答案':'正确答案'}：${esc(rightAnswer(q,order))}</p>`}${E.isWritten(q)?definitionPoints(q,answer.response):''}${q.brief?`<p>${esc(q.explanation)}</p>`:''}${hasBriefAnswer(q)?definitionDetails(q):`<p>${esc(q.explanation)}</p>`}${!answer.correct&&q.type==='fill'?'<p>填空按预设同义词判断。若你的表达意思相同，可对照标准关键词重新记忆。</p>':''}${hasBriefAnswer(q)?'':`<div class="source">依据：${esc(q.source)}${sourceLinks(q)}${q.homeworkId?`<a class="text-btn" href="#homework/${q.homeworkId}">查看教师原题与课堂原图 →</a>`:''}</div>`}</section>`:'';
return title('ONE QUESTION AT A TIME',esc(s.title),E.isWritten(q)?'先独立作答，再按要点自评；结果会记录在本机学习进度中。':'看清题干与条件，再选择你的答案。',`<button class="btn secondary small" data-action="nav" data-value="map">保存并返回</button>`)+`<div class="quiz-layout"><section class="quiz-card"><div class="quiz-top"><span class="quiz-count">题目 <b>${s.cursor+1}</b> / ${s.ids.length}</span>${starButton(q)}</div><div class="progress-track"><i style="width:${Object.keys(s.answers).length/s.ids.length*100}%"></i></div><div style="margin-top:22px">${tags(q)}</div><h2>${esc(q.prompt)}</h2><p class="quiz-hint">${E.isWritten(q)?'简答 · 自主作答 → 对照要点 → 记录自评。':q.type==='multi'?'多选题 · 选出全部正确项，少选或多选均不得分。':XT.typeOf(q)==='number'?'计算题 · 建议在纸上写清公式、代入与单位；网站自动核对最终数值，不评分书写过程。':q.type==='number'?'数值填空 · 填写课程要求的数值与单位。':q.type==='fill'?'关键词填空 · 支持题库已列出的常见同义答案。':'选定后点击“确认答案”，提交后可查看解析。'}</p>${form}<div class="form-error" id="form-error" role="alert"></div>${feedback}${sweetFeedback(q,answer)}<div class="quiz-actions"><span class="quiz-hint" style="margin:0">${answer?(answer.correct?'已记录本次掌握':'已加入待巩固错题'):'独立作答，印象更深。'}</span><button class="btn" data-action="${answer?'next':reviewing?'definition-grade':'submit'}">${answer?(s.cursor===s.ids.length-1?'查看本次结果':'下一题'):E.isWritten(q)?(reviewing?'记录自评':'提交并对照要点'):'确认答案'} ${icon('arrow',16)}</button></div></section><aside><section class="aside-card"><span class="eyebrow">THIS SESSION</span><h3>每一步都算数</h3><p>${s.mode==='stage'?'本关抽取 12 道题，答对 10 道即可解锁下一关。':s.mode==='boss'?'综合终章共 24 道题，答对 20 道即通关。':'练习不会改变关卡解锁，但会记录正确率和更新错题。'}</p><div class="question-dots">${s.ids.map((id,i)=>`<span class="qdot ${s.answers[id]?(s.answers[id].correct?'ok':'bad'):i===s.cursor?'current':''}" aria-label="第${i+1}题${s.answers[id]?(s.answers[id].correct?'答对':'答错'):'未答'}">${i+1}</span>`).join('')}</div><div class="divider"></div><div class="rule-line"><span>当前答对</span><strong>${Object.values(s.answers).filter(a=>a.correct).length} 题</strong></div></section><section class="aside-card" style="margin-top:18px"><h3>先理解，再记忆</h3><p>${E.isWritten(q)?'简答按关键词分点写清作用、组成、原因或过程。自评需依据你提交前的表达；全部要点掌握计为答对，否则加入错题本。':'选项顺序会变化。留意“至少”“大于”“按课程口径”等限定词，它们常常决定答案。'}</p></section></aside></div>`;}
function submit(){const s=state.session;if(!s||s.done)return;const q=byId[s.ids[s.cursor]];if(s.answers[q.id])return;if(E.isWritten(q)){const d=definitionDraft(q);if(d.reviewing)return;const text=document.getElementById('definition-input').value.trim();if(!text){document.getElementById('form-error').textContent='请先分点写出答案，再对照要点。';document.getElementById('definition-input').focus();return;}s.definitionDraft={id:q.id,text,reviewing:true,points:q.points.map(()=>false)};save();render();document.querySelector('.definition-review').focus({preventScroll:true});document.querySelector('.definition-review').scrollIntoView({block:'nearest'});return;}let response=choice;if(q.type==='fill'||q.type==='number')response=document.getElementById('answer-input').value.trim();if(response===null||response===undefined||response===''||(Array.isArray(response)&&!response.length)){document.getElementById('form-error').textContent='请先填写或选择答案。';return;}const correct=E.record(state,q,response);window.WATER_SOUND?.play(correct?'correct':'incorrect');s.answers[q.id]={response,correct};save();const y=window.scrollY;render();window.scrollTo(0,y);document.querySelector('.feedback')?.scrollIntoView({behavior:'smooth',block:'nearest'});document.querySelector('[data-action="next"]')?.focus({preventScroll:true});}
function advance(){const s=state.session;if(!s?.answers[s.ids[s.cursor]])return;if(SC.needsReview(state.sweet,s.ids[s.cursor])){toast('先留下一句易错提醒，再进入下一题。');document.getElementById('sweet-review-note')?.focus();return;}if(s.cursor===s.ids.length-1){E.finish(state,s);save();goto('result');window.WATER_SOUND?.play(s.result.passed?'complete':'review');}else{s.cursor++;choice=null;save();render();document.getElementById('main').scrollIntoView({block:'start'});document.querySelector('.quiz-card h2')?.setAttribute('tabindex','-1');document.querySelector('.quiz-card h2')?.focus({preventScroll:true});}}
function questionCard(q,open=false,answer){const order=q.options?(answer?state.session.orders[q.id]:q.options.map((_,i)=>i)):null;return `<article class="bank-item"><div class="bank-head">${tags(q)}${starButton(q)}</div><h3>${esc(q.prompt)}</h3>${q.options?`<div class="bank-options">${order.map((i,j)=>`<span>${String.fromCharCode(65+j)}. ${esc(q.options[i])}</span>`).join('')}</div>`:''}<details ${open?'open':''}><summary>${hasBriefAnswer(q)?'查看精简答案':'查看答案与解析'}</summary><div class="answer-detail">${q.brief?'':`<strong>${q.type==='definition'?'精简答案':E.isWritten(q)?'参考答案':'正确答案'}：${esc(rightAnswer(q,order))}</strong>`}${E.isWritten(q)?definitionPoints(q,answer?.response):''}${answer?`<div>本次回答：${esc(responseText(q,answer.response,order))}</div>`:''}${q.brief?`<p>${esc(q.explanation)}</p>`:''}${hasBriefAnswer(q)?definitionDetails(q):`<div>${esc(q.explanation)}</div><div class="source">依据：${esc(q.source)}${sourceLinks(q)}</div>`}</div></details></article>`;}
function resultView(){const s=state.session;if(!s?.done)return mapView();const r=s.result,challenge=['stage','boss'].includes(s.mode),wrong=s.ids.filter(id=>!s.answers[id].correct);return title('EVERY TRY COUNTS','这一次，又向前了一步。',esc(s.title))+`<section class="result"><div class="score-ring"><strong>${r.score}</strong><span>本次得分 / 100</span></div><div class="stars" style="font-size:21px;margin-bottom:17px">${'★'.repeat(r.stars)}${'☆'.repeat(3-r.stars)}</div><h2>${challenge?(r.passed?s.mode==='boss'?'恭喜，成为水系统设计师！':`第 ${s.ch} 关，顺利通关！`:'还差一点，把错题变成得分点。'):'练习完成，知识又扎实了一点。'}</h2><p>答对 ${r.correct} / ${r.count} 题 · ${challenge?(r.passed?s.mode==='stage'&&s.ch<8?'下一关已解锁。':'可以反复挑战，冲刺满星。':`还需答对 ${Math.max(0,Math.ceil(r.count*.8)-r.correct)} 题达到通关标准。`):'本次结果已计入学习记录。'}</p><div class="result-actions">${r.passed&&s.mode==='stage'&&s.ch<8?`<button class="btn" data-action="stage" data-value="${s.ch+1}">前往下一关 ${icon('arrow',15)}</button>`:''}${r.passed&&s.mode==='stage'&&s.ch===8?'<button class="btn" data-action="boss">挑战综合终章 →</button>':''}${wrong.length?'<button class="btn" data-action="retry-wrong">重练本次错题</button>':''}<button class="btn secondary" data-action="retry">再练一次</button><button class="btn secondary" data-action="nav" data-value="map">回到地图</button></div></section><section class="result-review"><div class="section-head"><h3>本次错题复盘</h3><small>${wrong.length} 道待巩固</small></div>${wrong.length?wrong.map(id=>questionCard(byId[id],true,s.answers[id])).join(''):'<div class="empty">'+icon('trophy')+'<h3>全部答对，做得扎实。</h3><p>可以进入下一关，或回到题库检验更多知识点。</p></div>'}</section>`;}
function filtered(){const list=Q.filter(q=>(filter.ch==='all'||q.ch===Number(filter.ch))&&(filter.type==='all'||(filter.type==='definition'?q.type==='definition':XT.typeOf(q)===filter.type))&&(filter.scope==='all'||filter.scope==='starred'&&state.starred.includes(q.id)||filter.scope==='unseen'&&!state.stats[q.id])&&(!filter.search||(q.prompt+' '+q.topic+' '+q.explanation).toLowerCase().includes(filter.search.toLowerCase())));return filter.type==='short'?list.sort((a,b)=>(a.type==='short'?0:1)-(b.type==='short'?0:1)):list;}
function filterBar(){return `<div class="toolbar"><input id="search" aria-label="搜索题目或考点" placeholder="搜索题目或考点，例如：水封、第二循环…" value="${esc(filter.search)}"><select id="chapter-filter" aria-label="筛选章节"><option value="all">全部章节</option>${chapters.map(c=>`<option value="${c.id}" ${filter.ch===String(c.id)?'selected':''}>${c.id}. ${c.title}</option>`).join('')}</select><select id="type-filter" aria-label="筛选题型"><option value="all">全部题型</option>${filter.type==='definition'?'<option value="definition" selected>简答 · 名词解释复习</option>':''}${Object.entries(types).map(([k,v])=>`<option value="${k}" ${filter.type===k?'selected':''}>${v}</option>`).join('')}</select><select id="scope-filter" aria-label="筛选练习状态">${[['all','全部题目'],['starred','已收藏'],['unseen','尚未练过']].map(([v,t])=>`<option value="${v}" ${filter.scope===v?'selected':''}>${t}</option>`).join('')}</select></div>`;}
function listBody(list){const pages=Math.max(1,Math.ceil(list.length/10));page=Math.min(page,pages);return `<div class="section-head"><small>共 ${list.length} 道题 · 第 ${page} / ${pages} 页</small><button class="text-btn" data-action="nav" data-value="notes">先看考点速记 →</button></div>${list.length?list.slice((page-1)*10,page*10).map(q=>questionCard(q)).join(''):'<div class="empty"><h3>没有匹配的题目</h3><p>试试更换关键词、章节或题型。</p></div>'}<div class="pagination"><button class="btn secondary small" data-action="page" data-value="${page-1}" ${page===1?'disabled':''}>上一页</button><span>${page} / ${pages}</span><button class="btn secondary small" data-action="page" data-value="${page+1}" ${page===pages?'disabled':''}>下一页</button></div>`;}
function examTypes(){const hints={fill:'文字填空 · 记准关键词',boolean:'辨别对错 · 看清限定词',single:'四选一 · 找到最合适项',multi:'选全正确项 · 注意漏选',short:'24 道教师简答＋32 道名词解释',number:'列式计算 · 注意单位与精度'};return `<section class="exam-types" aria-label="六类考试题型"><div class="section-head"><h2>按考试题型练习</h2><small>填空 · 判断 · 单选 · 多选 · 简答 · 计算</small></div><div class="exam-type-grid">${Object.entries(types).map(([key,label],i)=>`<button class="exam-type ${screen==='bank'&&filter.type===key?'active':''}" data-action="exam-type" data-value="${key}" aria-pressed="${screen==='bank'&&filter.type===key}"><span class="exam-type-no">0${i+1}</span><span><strong>${label}</strong><small>${hints[key]}</small></span><b>${Q.filter(q=>XT.typeOf(q)===key).length}<small>题</small></b></button>`).join('')}</div><p class="exam-type-note">简答先写答案，再按要点自评；题量为本站练习储备，不代表考试分值。</p></section>`;}
function bankView(){return title('PRACTICE AT YOUR OWN PACE','练习，由你决定。','按考试的六类题型训练，也可以结合章节筛选。简答含教师提纲与名词解释复习。',`<div class="bank-actions"><button class="btn secondary" data-action="definitions">名词解释复习 · ${Q.filter(q=>q.type==='definition').length} 题</button><button class="btn" data-action="free">抽题练习 →</button></div>`)+examTypes()+filterBar()+`<section id="bank-list">${listBody(filtered())}</section>`;}
function wrongView(){const list=state.wrong.map(id=>byId[id]);return title('TURN MISTAKES INTO PROGRESS','错过一次，就记牢一点。','答错自动收录；之后在任意练习中答对，会自动移出待巩固列表。',list.length?'<button class="btn" data-action="wrong-all">重练全部错题 →</button>':'')+(list.length?listBody(list):`<div class="empty">${icon('check')}<h3>这里暂时没有待巩固错题。</h3><p>开始一轮挑战，遇到的薄弱点会自动汇集到这里。</p><button class="btn" data-action="nav" data-value="map">前往闯关地图</button></div>`);}
function dateText(value){const dt=new Date(value);return Number.isNaN(dt.getTime())?'':dt.toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});}
function recordsView(){return title('YOUR LEARNING JOURNEY','进步，都有迹可循。','掌握度按每道题最近一次作答统计；正确率按全部作答次数统计，包含简答与名词解释的自评结果。')+stats()+`<div class="record-layout"><section class="aside-card"><h3>章节掌握度</h3>${chapters.map(c=>{const total=Q.filter(q=>q.ch===c.id).length,mastered=Q.filter(q=>q.ch===c.id&&state.stats[q.id]?.last===true).length;return `<div class="bar-item"><div class="rule-line"><span>${c.id}. ${c.title}</span><span>${mastered}/${total} 题</span></div><div class="progress-track"><i style="width:${mastered/total*100}%"></i></div></div>`;}).join('')}</section><section class="aside-card"><h3>最近完成的练习</h3>${state.history.length?state.history.slice(0,8).map(h=>`<div class="history-row"><div>${esc(h.title)}<small>${esc(dateText(h.date))} · 答对 ${h.correct}/${h.count}</small></div><strong class="score-num">${h.score}<small style="display:inline"> 分</small></strong></div>`).join(''):'<p>完成一轮练习后，这里会记录本次成绩。</p>'}</section></div><section class="info-box"><h3>把进度随身带走</h3><p>进度、课后题草稿与掌握标记、心心、易错提醒、奖励卡与考试时间一起保存在当前浏览器。换设备前导出备份，再在新设备导入即可；不会自动同步。旧版备份也可导入；缺少的课后题记录或甜蜜奖励会从零开始。</p><div class="record-actions"><button class="btn" data-action="export">导出进度备份</button><button class="btn secondary" data-action="import">导入进度备份</button><button class="btn secondary" data-action="starred">练习收藏题（${state.starred.length}）</button><button class="text-btn" data-action="reset">清空本机进度</button></div></section>`;}
function notesView(){return title('QUICK RECALL','先搭框架，再做题。','八张速记卡，串起七章考点与核心公式。',`<button class="btn secondary" data-action="nav" data-value="bank">回到题库</button>`)+`<div class="note-grid">${chapters.map(c=>`<article class="note-card"><div class="stage-top"><div class="stage-icon">${icon(c.icon)}</div><span class="stage-no">${String(c.id).padStart(2,'0')}</span></div><h3>${c.title}</h3><ol>${c.notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ol><button class="text-btn" data-action="chapter-bank" data-value="${c.id}">练习本章题目 →</button></article>`).join('')}</div>`;}
function aboutView(){return title('ABOUT THIS QUESTION BANK','题库有依据，复习有方向。','根据已有复习重点重新组织成可练习、可复盘的题目。')+`<section class="info-box"><h3>范围与来源</h3><ul>${D.sources.items.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><section class="info-box"><h3>闯关规则</h3><p>前 7 关对应课程章节，第 8 关为公式计算。每关从本章题库中抽取 12 道，至少答对 10 道即可解锁下一关。最后的综合终章从每章抽 3 道，共 24 道，至少答对 20 道通关。</p><p>单选、判断、填空每题按对错计分；多选全部选对才得分，无部分分。数值题接受题干要求精度范围内的答案。选项顺序随机；星级由整轮正确率决定。自由练习不解锁关卡。</p><p>简答与名词解释先独立作答，再对照参考答案逐项自评。每个要点按 1 分练习，全部要点掌握记为答对，否则加入错题本；学习记录与通关分数包含自评结果。措辞可不同，但不应有概念错误。练习要点不等同老师正式评分细则。</p><p>错题答对后自动移出待巩固列表。如需长期保留，可点星号收藏。随时返回地图不会丢失当前已提交答案；开始另一轮会提示替换未完成挑战。</p><button class="btn" data-action="nav" data-value="map">开始复习 →</button></section>`;}
function render(){SC.today(state.sweet);let body;switch(screen){case'homework':body=HW.view(state,{title,materialLink,chapters});break;case'materials':body=materialsView();break;case'reader':body=readerView();break;case'quiz':body=quizView();break;case'result':body=resultView();break;case'bank':body=bankView();break;case'wrong':body=wrongView();break;case'records':body=recordsView();break;case'notes':body=notesView();break;case'about':body=aboutView();break;default:body=mapView();}shell(body);window.WATER_SOUND?.sync();const s=state.session,qid=s?.ids[s.cursor];window.WATER_MOTION?.render({page:screen==='quiz'?`quiz:${qid}`:screen==='reader'?`reader:${materialId}:${materialPage}`:screen,celebrate:screen==='result'&&s?.result?.passed&&['stage','boss'].includes(s.mode)?s.ids.join('|'):null});}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;e.preventDefault();const a=b.dataset.action,v=b.dataset.value;if(HW.action(a,v,{state,save,render,goto,toast}))return;if(sweetAction(a,v))return;if(a==='nav')return goto(v);if(a==='reader-zoom'){const wrap=document.getElementById('review-page-wrap');const yes=wrap.classList.toggle('zoomed');b.setAttribute('aria-pressed',String(yes));b.textContent=yes?'适应宽度':'放大阅读';return;}if(a==='read-material')return openMaterial(v,b.dataset.page);if(a==='material-jump'){const input=document.getElementById('material-page');const n=Number(input.value);if(!Number.isInteger(n)||n<1||n>materialFile().pages){toast('请输入 1 到 '+materialFile().pages+' 之间的整数页码。');return;}return openMaterial(materialId,n);}if(a==='stage')return start('stage',Number(v));if(a==='boss')return start('boss');if(a==='free')return start('free');if(a==='resume')return goto(state.session?.done?'result':'quiz');if(a==='wrong-all')return start('wrong');if(a==='starred')return start('starred');if(a==='retry-wrong')return start('wrong',null,state.session.ids.filter(id=>!state.session.answers[id].correct));if(a==='retry'){const s=state.session;return start(s.mode,s.ch,['stage','boss'].includes(s.mode)?undefined:s.ids);}if(a==='exam-type'){if(!Object.hasOwn(types,v))return;filter={ch:'all',type:v,scope:'all',search:''};return goto('bank');}if(a==='definitions'){filter={ch:'all',type:'definition',scope:'all',search:''};return goto('bank');}if(a==='definition-grade')return gradeDefinition();if(a==='submit')return submit();if(a==='next')return advance();
if(a==='option'||a==='boolean'){const q=byId[state.session.ids[state.session.cursor]];if(state.session.answers[q.id])return;const value=a==='boolean'?v==='true':Number(v);if(q.type==='multi'){choice=Array.isArray(choice)?choice:[];choice=choice.includes(value)?choice.filter(x=>x!==value):[...choice,value];}else choice=value;const y=window.scrollY;render();window.scrollTo(0,y);const picked=document.querySelector(`[data-action="${a}"][data-value="${v}"]`);picked?.focus({preventScroll:true});window.WATER_MOTION?.choose(picked);return;}
if(a==='star'){const yes=state.starred.includes(v);state.starred=yes?state.starred.filter(x=>x!==v):[...state.starred,v];save();b.textContent=yes?'☆':'★';b.setAttribute('aria-label',yes?'收藏本题':'取消收藏');b.setAttribute('aria-pressed',String(!yes));toast(yes?'已取消收藏':'已收藏，可在题库中筛选');return;}
if(a==='page'){page=Number(v);render();window.scrollTo(0,0);return;}if(a==='chapter-bank'){filter={ch:v,type:'all',scope:'all',search:''};return goto('bank');}
if(a==='export'){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='甜蜜蜜复习-学习进度-'+new Date().toISOString().slice(0,10)+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return toast('进度备份已导出。');}
if(a==='import')return document.getElementById('import-file').click();if(a==='reset')return confirmAction('清空本机学习进度？','这会删除本机的关卡、答题记录、课后题草稿与标记、错题、收藏、心心和易错提醒，并重置考试时间。建议先导出备份；此操作不会删除题库。',()=>{state=E.fresh();loadWarning=false;save();goto('map');toast('已清空学习进度。');},'确认清空');});
document.addEventListener('input',e=>{HW.input(e,state,save,chapters);if(e.target.id==='definition-input'){const q=byId[state.session.ids[state.session.cursor]],d=definitionDraft(q);if(!d.reviewing&&!state.session.answers[q.id]){state.session.definitionDraft={...d,text:e.target.value};save();}}if(e.target.id==='answer-input')choice=e.target.value;if(e.target.id==='search'){filter.search=e.target.value;page=1;document.getElementById('bank-list').innerHTML=listBody(filtered());}});
document.addEventListener('change',e=>{HW.change(e,render);if(e.target.matches('[data-definition-point]')){const d=state.session?.definitionDraft,i=Number(e.target.dataset.definitionPoint);if(d?.reviewing&&Number.isInteger(i)&&i>=0&&i<d.points.length&&!state.session.answers[d.id]){d.points[i]=e.target.checked;save();document.getElementById('definition-score').textContent='已勾选 '+d.points.filter(Boolean).length+' / '+d.points.length+' 个要点';}return;}if(e.target.id==='reference-select')return openMaterial('answers',e.target.value);if(e.target.id==='material-select')return openMaterial(e.target.value,1);const key={'chapter-filter':'ch','type-filter':'type','scope-filter':'scope'}[e.target.id];if(key){filter[key]=e.target.value;page=1;try{history.replaceState(null,'',location.pathname+location.search+'#practice/'+filter.type);}catch(err){}render();}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='material-page'){e.preventDefault();document.querySelector('[data-action="material-jump"]').click();}if(e.key==='Enter'&&e.target.id==='answer-input'){e.preventDefault();submit();}});
document.getElementById('import-file').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2*1024*1024)throw new Error('备份文件过大');const incoming=E.validateState(JSON.parse(await f.text()),Q);confirmAction('导入这份学习进度？','导入会替换当前浏览器中的学习进度。建议先导出现有进度备份。',()=>{state=incoming;loadWarning=false;save();goto('records');toast('进度已导入，可回到地图继续答题。');},'确认导入');}catch(error){toast('无法导入：'+(error instanceof SyntaxError?'请选择有效的 JSON 备份文件':error.message));}finally{e.target.value='';}});
// Detect disabled storage without replacing an existing record.
try{localStorage.setItem(KEY+'-check','1');localStorage.removeItem(KEY+'-check');}catch(e){storageOK=false;}
setInterval(()=>{const changed=state.sweet.day.date!==SC.dayKey();if(changed){SC.today(state.sweet);save();if(screen==='map'){render();return;}}const clock=document.getElementById('sweet-countdown');if(clock)clock.innerHTML=sweetClock(SC.countdown(state.sweet));},30000);
readMaterialRoute();
window.addEventListener('hashchange',()=>{if(readMaterialRoute())render();});
render();
})();
